const chapterFor = id => id <= 40 ? 1 : id <= 47 ? 2 : id <= 54 ? 3 : id <= 61 ? 4 : id <= 68 ? 5 : id <= 75 ? 6 : id <= 82 ? 7 : id <= 88 ? 8 : id <= 94 ? 9 : 10;
const topicFor = chapter => [null,'early-cities','ancient-worlds','classical-age','silk-roads','medieval-lives','age-of-exploration','revolutions','modern-times','people-and-power','threads-of-time'][chapter];
const chapterTheme = chapter => ['','First Cities','Ancient Worlds','Classical Age','Silk Roads','Medieval Lives','Age of Exploration','Revolutions','Modern Times','People & Power','Threads of Time'][chapter];

function add(id, q, correctText, why, difficulty, subtopic, answerFamily, wrongTexts, rationaleNote, sourceKey, claim) {
  const chapterId = chapterFor(id);
  const source = SOURCES[sourceKey];
  return {
    id:'history-extra-' + String(id).padStart(3,'0'), q, correctText, why, difficulty,
    topicId:topicFor(chapterId), subtopic:chapterTheme(chapterId) + ' · ' + subtopic,
    chapterId, answerFamily,
    distractors:wrongTexts.map(text => ({text, rationale:text + ' is a plausible ' + answerFamily + ' alternative, but ' + rationaleNote})),
    source:{title:source.title,url:source.url,claim,status:'verified',lastVerified:VERIFIED_ON},
    verifiedAt:VERIFIED_ON,
  };
}

